#!/usr/bin/env python3"""Тестовый скрипт для проверки новых функций работы с сообщениями"""import sysimport os# Добавляем родительскую директорию в путь Pythonparent_dir = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))sys.path.insert(0, parent_dir)from services.conversations.conversation_service import ConversationServicefrom services.agents.agent_service import AgentServicefrom core.database import get_sessionfrom models.user import Userfrom models.agent import Agentfrom models.conversation import Conversationfrom models.message import Messagefrom sqlmodel import Session, selectdef test_message_functions():    """Тестирует новые функции работы с сообщениями"""        print("🧪 Тестирование новых функций работы с сообщениями...")        try:        # Создаем сервисы        conversation_service = ConversationService()        agent_service = AgentService()                # Получаем сессию базы данных        session_gen = get_session()        session = next(session_gen)                # Находим первого пользователя        user = session.exec(select(User)).first()        if not user:            print("❌ Пользователи не найдены. Создайте пользователя сначала.")            return False                # Находим первого агента        agent = session.exec(select(Agent)).first()        if not agent:            print("❌ Агенты не найдены. Создайте агента сначала.")            return False                print(f"👤 Используем пользователя: {user.username}")        print(f"🤖 Используем агента: {agent.name}")                # Создаем тестовый разговор        print("\n📝 Создаем тестовый разговор...")        conversation = conversation_service.create_conversation(            agent_id=agent.id,            title="Тестовый чат",            user_id=user.id        )        print(f"✅ Разговор создан: {conversation.id}")                # Создаем тестовые сообщения        print("\n💬 Создаем тестовые сообщения...")                # Сообщение от пользователя        user_message = conversation_service.save_message(            conversation_id=conversation.id,            content="Привет! Это тестовое сообщение от пользователя.",            is_from_user=True        )        print(f"✅ Сообщение от пользователя создано: {user_message.id}")                # Сообщение от агента        agent_message = conversation_service.save_message(            conversation_id=conversation.id,            content="Привет! Это ответ от агента.",            is_from_user=False,            agent_id=agent.id        )        print(f"✅ Сообщение от агента создано: {agent_message.id}")                # Тестируем закрепление сообщения        print("\n📌 Тестируем закрепление сообщения...")        pin_success = conversation_service.pin_message(            conversation_id=conversation.id,            message_id=user_message.id        )        if pin_success:            print("✅ Сообщение успешно закреплено")        else:            print("❌ Ошибка при закреплении сообщения")                # Проверяем закрепленное сообщение        pinned = conversation_service.get_pinned_message(conversation.id)        if pinned:            print(f"✅ Закрепленное сообщение найдено: {pinned['content'][:50]}...")        else:            print("❌ Закрепленное сообщение не найдено")                # Тестируем открепление        print("\n📌 Тестируем открепление сообщения...")        unpin_success = conversation_service.unpin_message(conversation.id)        if unpin_success:            print("✅ Сообщение успешно откреплено")        else:            print("❌ Ошибка при откреплении сообщения")                # Тестируем мягкое удаление        print("\n🗑️ Тестируем удаление сообщения...")        delete_success = conversation_service.delete_message(agent_message.id)        if delete_success:            print("✅ Сообщение успешно удалено (мягкое удаление)")        else:            print("❌ Ошибка при удалении сообщения")                # Проверяем, что удаленное сообщение не показывается        messages = conversation_service.get_conversation_messages(conversation.id)        print(f"📊 Количество активных сообщений: {len(messages)}")                # Очищаем тестовые данные        print("\n🧹 Очищаем тестовые данные...")        conversation_service.delete_conversation(conversation.id)        print("✅ Тестовые данные очищены")                print("\n🎉 Все тесты прошли успешно!")        return True                except Exception as e:        print(f"❌ Ошибка во время тестирования: {e}")        import traceback        traceback.print_exc()        return Falseif __name__ == "__main__":    success = test_message_functions()    if success:        print("\n✅ Все функции работают корректно!")    else:        print("\n❌ Обнаружены проблемы в работе функций")